/**
 * Synthesises the editor's "studio" sound effects (whooshes, risers, hits, pops…) from scratch
 * and writes them to public/sfx/synth/*.mp3. Everything is generated by this script, so the
 * sounds are original works released under CC0 1.0.
 *
 *   node scripts/build-sfx-synth.mjs
 *
 * Encoding uses the ffmpeg binary that ships with @remotion/compositor-*.
 */
import { execFileSync } from "node:child_process";
import { mkdirSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const SR = 44100;
const root = fileURLToPath(new URL("..", import.meta.url));
const outDir = join(root, "public", "sfx", "synth");
const tmp = join(tmpdir(), "ams-sfx");

// ---------- tiny DSP toolkit ----------

let seed = 1234567;
const rand = () => {
  seed = (seed * 16807) % 2147483647;
  return (seed - 1) / 2147483646;
};
const noise = () => rand() * 2 - 1;

const buffer = (seconds) => new Float32Array(Math.round(seconds * SR));

/** RBJ biquad band-pass with per-sample centre frequency. */
const bandpass = (input, freqAt, q = 1.2) => {
  const out = new Float32Array(input.length);
  let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
  for (let i = 0; i < input.length; i++) {
    const w = (2 * Math.PI * Math.min(freqAt(i / input.length), SR / 2.2)) / SR;
    const alpha = Math.sin(w) / (2 * q);
    const b0 = alpha, b2 = -alpha, a0 = 1 + alpha, a1 = -2 * Math.cos(w), a2 = 1 - alpha;
    const y = (b0 * input[i] + b2 * x2 - a1 * y1 - a2 * y2) / a0;
    x2 = x1; x1 = input[i]; y2 = y1; y1 = y;
    out[i] = y;
  }
  return out;
};

const lowpass = (input, cutoffAt) => {
  const out = new Float32Array(input.length);
  let y = 0;
  for (let i = 0; i < input.length; i++) {
    const c = typeof cutoffAt === "function" ? cutoffAt(i / input.length) : cutoffAt;
    const a = 1 - Math.exp((-2 * Math.PI * c) / SR);
    y += a * (input[i] - y);
    out[i] = y;
  }
  return out;
};

const highpass = (input, cutoff) => {
  const low = lowpass(input, cutoff);
  return input.map((v, i) => v - low[i]);
};

const sweepTone = (seconds, f0, f1, shape = "sine", curve = 1) => {
  const out = buffer(seconds);
  let phase = 0;
  for (let i = 0; i < out.length; i++) {
    const p = Math.pow(i / out.length, curve);
    const f = f0 * Math.pow(f1 / f0, p);
    phase += (2 * Math.PI * f) / SR;
    const s = Math.sin(phase);
    out[i] = shape === "saw" ? ((phase / Math.PI) % 2) - 1 : shape === "square" ? Math.sign(s) : s;
  }
  return out;
};

const env = (buf, fn) => buf.map((v, i) => v * fn(i / buf.length, i / SR));
const mix = (...bufs) => {
  const len = Math.max(...bufs.map((b) => b.length));
  const out = new Float32Array(len);
  for (const b of bufs) for (let i = 0; i < b.length; i++) out[i] += b[i];
  return out;
};
const gain = (buf, g) => buf.map((v) => v * g);
const offset = (buf, seconds) => {
  const pad = Math.round(seconds * SR);
  const out = new Float32Array(buf.length + pad);
  out.set(buf, pad);
  return out;
};
const noiseBuf = (seconds) => buffer(seconds).map(noise);
const bell = (p, peak = 0.5, sharp = 2) => Math.pow(Math.sin(Math.PI * Math.min(1, Math.max(0, p < peak ? (p / peak) * 0.5 : 0.5 + ((p - peak) / (1 - peak)) * 0.5))), sharp);
const decay = (rate) => (_p, t) => Math.exp(-t * rate);
const attackDecay = (attack, rate) => (_p, t) => (t < attack ? t / attack : Math.exp(-(t - attack) * rate));

/** Simple feedback-delay reverb for tails. */
const reverb = (buf, seconds = 1.2, wet = 0.3) => {
  const out = new Float32Array(buf.length + Math.round(seconds * SR));
  out.set(buf);
  const taps = [0.0297, 0.0371, 0.0411, 0.0437].map((d) => Math.round(d * SR));
  const fb = 0.72;
  const lines = taps.map((t) => new Float32Array(t));
  const idx = taps.map(() => 0);
  for (let i = 0; i < out.length; i++) {
    const dry = i < buf.length ? buf[i] : 0;
    let acc = 0;
    lines.forEach((line, k) => {
      const v = line[idx[k]];
      acc += v;
      line[idx[k]] = dry + v * fb;
      idx[k] = (idx[k] + 1) % line.length;
    });
    out[i] = (i < buf.length ? buf[i] : 0) + (acc / lines.length) * wet;
  }
  return out;
};

const bellTone = (seconds, freqs, rate = 3) =>
  mix(...freqs.map(([f, a], k) => env(sweepTone(seconds, f, f), decay(rate * (1 + k * 0.6))).map((v) => v * a)));

const normalize = (buf, peak = 0.89) => {
  let max = 0;
  for (const v of buf) max = Math.max(max, Math.abs(v));
  const g = max ? peak / max : 1;
  // short fade at both ends to avoid clicks
  const fade = Math.round(0.004 * SR);
  return buf.map((v, i) => v * g * Math.min(1, i / fade, (buf.length - 1 - i) / fade));
};

// ---------- sound designs ----------

const SOUNDS = {
  "whoosh-soft": () => env(bandpass(noiseBuf(0.9), (p) => 300 + 2400 * bell(p, 0.55, 1), 1.4), (p) => bell(p, 0.55, 2)),
  "whoosh-fast": () => env(bandpass(noiseBuf(0.45), (p) => 600 + 5000 * bell(p, 0.5, 1), 1.8), (p) => bell(p, 0.5, 3)),
  "whoosh-deep": () =>
    mix(
      env(bandpass(noiseBuf(1.3), (p) => 120 + 900 * bell(p, 0.6, 1), 1), (p) => bell(p, 0.6, 2)),
      gain(env(sweepTone(1.3, 70, 45), (p) => bell(p, 0.6, 3)), 0.35),
    ),
  "swoosh-up": () => env(bandpass(noiseBuf(0.7), (p) => 400 * Math.pow(18, p), 2), (p) => Math.pow(p, 1.5) * (1 - Math.pow(p, 8))),
  "swoosh-down": () => env(bandpass(noiseBuf(0.7), (p) => 7000 * Math.pow(1 / 18, p), 2), (p) => Math.pow(1 - p, 1.4) * Math.min(1, p * 30)),
  "transition-swipe": () => mix(env(bandpass(noiseBuf(0.6), (p) => 900 + 6000 * p, 2.5), (p) => bell(p, 0.7, 2)), gain(env(sweepTone(0.6, 200, 900), (p) => bell(p, 0.7, 4)), 0.15)),
  "riser-short": () =>
    mix(
      env(bandpass(noiseBuf(2), (p) => 300 * Math.pow(25, p), 3), (p) => Math.pow(p, 2)),
      gain(env(sweepTone(2, 110, 880, "saw", 1.2), (p) => Math.pow(p, 2.2)), 0.18),
    ),
  "riser-long": () =>
    mix(
      env(bandpass(noiseBuf(4.5), (p) => 200 * Math.pow(40, p), 2.5), (p) => Math.pow(p, 2.4)),
      gain(env(sweepTone(4.5, 80, 1200, "saw", 1.3), (p) => Math.pow(p, 2.6)), 0.15),
      gain(env(sweepTone(4.5, 82, 1210, "saw", 1.3), (p) => Math.pow(p, 2.6)), 0.15),
    ),
  downlifter: () =>
    mix(
      env(bandpass(noiseBuf(2.2), (p) => 8000 * Math.pow(1 / 40, p), 2.5), (p) => Math.pow(1 - p, 1.8) * Math.min(1, p * 40)),
      gain(env(sweepTone(2.2, 400, 40), (p) => Math.pow(1 - p, 1.5)), 0.4),
    ),
  "impact-boom": () =>
    reverb(
      mix(
        env(sweepTone(2.2, 90, 32, "sine", 0.4), attackDecay(0.005, 2.2)),
        gain(env(lowpass(noiseBuf(1), 1800), attackDecay(0.002, 9)), 0.8),
      ),
      1.5,
      0.25,
    ),
  "cinematic-hit": () =>
    reverb(
      mix(
        env(sweepTone(2.5, 65, 38, "sine", 0.5), attackDecay(0.004, 1.6)),
        gain(env(highpass(noiseBuf(1.5), 2000), attackDecay(0.001, 5)), 0.35),
        gain(env(sweepTone(2.5, 220, 200, "saw"), attackDecay(0.003, 3)), 0.12),
      ),
      2.2,
      0.4,
    ),
  "sub-drop": () => env(sweepTone(3, 120, 30, "sine", 0.6), (p) => Math.min(1, p * 60) * Math.pow(1 - p, 1.2)),
  "punch-hit": () => mix(env(sweepTone(0.35, 180, 50), attackDecay(0.002, 14)), gain(env(lowpass(noiseBuf(0.2), 3500), attackDecay(0.001, 35)), 0.7)),
  pop: () => env(sweepTone(0.14, 380, 1100, "sine", 0.6), attackDecay(0.003, 28)),
  "pop-bubble": () => mix(env(sweepTone(0.18, 500, 1600, "sine", 0.4), attackDecay(0.004, 22)), offset(gain(env(sweepTone(0.12, 700, 1800), attackDecay(0.003, 30)), 0.5), 0.07)),
  "pop-cartoon": () => env(sweepTone(0.3, 250, 1400, "sine", 0.3), (p) => Math.sin(Math.PI * p) * Math.exp(-p * 2)),
  ding: () => reverb(bellTone(1.6, [[1320, 1], [2640, 0.35], [3960, 0.15]], 2.6), 1, 0.2),
  "chime-success": () =>
    reverb(mix(bellTone(1.2, [[880, 1], [1760, 0.3]], 3.5), offset(bellTone(1.2, [[1108.7, 1], [2217, 0.3]], 3.5), 0.12), offset(bellTone(1.6, [[1318.5, 1], [2637, 0.3]], 2.5), 0.24)), 1.2, 0.25),
  notification: () => mix(bellTone(0.5, [[1568, 1], [3136, 0.2]], 8), offset(bellTone(0.9, [[2093, 1], [4186, 0.2]], 5), 0.11)),
  "error-buzz": () => env(lowpass(sweepTone(0.45, 140, 120, "square"), 1800), (p) => (Math.floor(p * 6) % 2 ? 0.25 : 1) * (1 - p)),
  "magic-sparkle": () => {
    let out = buffer(1.8);
    for (let k = 0; k < 28; k++) {
      const f = 1800 + rand() * 4200;
      out = mix(out, offset(gain(env(sweepTone(0.4, f, f * 1.02), decay(9)), 0.25 + rand() * 0.4), k * 0.045 + rand() * 0.03));
    }
    return reverb(out, 1.2, 0.35);
  },
  glitch: () => {
    const out = buffer(0.8);
    let i = 0;
    while (i < out.length) {
      const len = Math.round((0.01 + rand() * 0.06) * SR);
      const type = Math.floor(rand() * 3);
      const f = 80 + rand() * 1800;
      for (let j = 0; j < len && i < out.length; j++, i++) {
        const t = j / SR;
        out[i] = type === 0 ? noise() * 0.6 : type === 1 ? Math.sign(Math.sin(2 * Math.PI * f * t)) * 0.5 : Math.round(Math.sin(2 * Math.PI * f * t) * 3) / 3;
      }
    }
    return out;
  },
  "static-noise": () => env(bandpass(noiseBuf(2.5), () => 2500, 0.5), (p) => Math.min(1, p * 20, (1 - p) * 20) * (0.7 + 0.3 * Math.sin(p * 40))),
  "censor-beep": () => env(sweepTone(0.7, 1000, 1000), (p) => Math.min(1, p * 100, (1 - p) * 100) * 0.6),
  "reverse-cymbal": () => env(highpass(noiseBuf(2), 3500), (p) => Math.pow(p, 3) * Math.min(1, (1 - p) * 60)),
  "cymbal-crash": () => reverb(env(highpass(noiseBuf(2.5), 4000), attackDecay(0.002, 2)), 1, 0.2),
  kick: () => env(sweepTone(0.5, 150, 45, "sine", 0.25), attackDecay(0.002, 9)),
  snare: () => mix(gain(env(sweepTone(0.25, 220, 180), attackDecay(0.001, 25)), 0.6), env(highpass(noiseBuf(0.3), 1500), attackDecay(0.001, 16))),
  clap: () => {
    let out = buffer(0.5);
    for (let k = 0; k < 4; k++) out = mix(out, offset(env(bandpass(noiseBuf(0.25), () => 1400, 1.5), attackDecay(0.001, k === 3 ? 14 : 60)), k * 0.012));
    return reverb(out, 0.4, 0.2);
  },
  "drum-roll": () => {
    let out = buffer(3);
    for (let t = 0, k = 0; t < 2.6; t += 0.055, k++) out = mix(out, offset(gain(env(highpass(noiseBuf(0.12), 1200), attackDecay(0.001, 40)), 0.3 + 0.7 * (t / 2.6)), t));
    return mix(out, offset(env(highpass(noiseBuf(1.2), 3000), attackDecay(0.002, 3)), 2.65), offset(env(sweepTone(0.6, 140, 45), attackDecay(0.002, 7)), 2.65));
  },
  "heart-beat": () => {
    const beat = (at, f) => offset(env(sweepTone(0.25, f, f * 0.6), attackDecay(0.01, 14)), at);
    let out = buffer(3.2);
    for (let k = 0; k < 4; k++) out = mix(out, beat(k * 0.8, 70), gain(beat(k * 0.8 + 0.22, 60), 0.7));
    return lowpass(out, 400);
  },
  "dark-drone": () => {
    const seconds = 8;
    const voices = [55, 55.4, 82.4, 110.6].map((f) => sweepTone(seconds, f, f, "saw"));
    return env(lowpass(mix(...voices), (p) => 300 + 500 * Math.sin(Math.PI * p)), (p) => Math.min(1, p * 4, (1 - p) * 4));
  },
  "tension-pulse": () => {
    let out = buffer(4);
    for (let t = 0; t < 4; t += 0.5) out = mix(out, offset(env(sweepTone(0.4, 55, 50, "saw"), attackDecay(0.005, 6)), t));
    return lowpass(out, 700);
  },
  "laser-zap": () => env(sweepTone(0.35, 2400, 180, "square", 0.6), attackDecay(0.002, 9)),
  "coin-collect": () => mix(env(sweepTone(0.1, 988, 988, "square"), () => 0.4), offset(env(sweepTone(0.4, 1319, 1319, "square"), decay(8)), 0.08)),
  "typing-burst": () => {
    let out = buffer(1.8);
    for (let t = 0; t < 1.6; t += 0.07 + rand() * 0.09) out = mix(out, offset(gain(env(bandpass(noiseBuf(0.05), () => 2500 + rand() * 2000, 2), attackDecay(0.0005, 90)), 0.5 + rand() * 0.5), t));
    return out;
  },
  "camera-shutter": () => mix(env(bandpass(noiseBuf(0.08), () => 3000, 1.5), attackDecay(0.001, 70)), offset(env(bandpass(noiseBuf(0.1), () => 2200, 1.5), attackDecay(0.001, 50)), 0.09)),
  "tape-stop": () => env(sweepTone(1.2, 440, 30, "saw", 0.5), (p) => (1 - p) * 0.6),
  "wind-ambience": () => env(bandpass(noiseBuf(10), (p) => 400 + 300 * Math.sin(p * 9) + 200 * Math.sin(p * 23), 0.8), (p) => Math.min(1, p * 5, (1 - p) * 5) * (0.6 + 0.4 * Math.sin(p * 11))),
  "rain-ambience": () => {
    let out = lowpass(noiseBuf(10), 2500);
    out = gain(out, 0.5);
    for (let k = 0; k < 400; k++) out = mix(out, offset(gain(env(bandpass(noiseBuf(0.03), () => 3000 + rand() * 4000, 3), attackDecay(0.0005, 120)), rand() * 0.6), rand() * 9.9));
    return env(out, (p) => Math.min(1, p * 8, (1 - p) * 8));
  },
};

// ---------- output ----------

const writeWav = (path, samples) => {
  const data = Buffer.alloc(44 + samples.length * 2);
  data.write("RIFF", 0);
  data.writeUInt32LE(36 + samples.length * 2, 4);
  data.write("WAVEfmt ", 8);
  data.writeUInt32LE(16, 16);
  data.writeUInt16LE(1, 20);
  data.writeUInt16LE(1, 22);
  data.writeUInt32LE(SR, 24);
  data.writeUInt32LE(SR * 2, 28);
  data.writeUInt16LE(2, 32);
  data.writeUInt16LE(16, 34);
  data.write("data", 36);
  data.writeUInt32LE(samples.length * 2, 40);
  for (let i = 0; i < samples.length; i++) data.writeInt16LE(Math.round(Math.max(-1, Math.min(1, samples[i])) * 32767), 44 + i * 2);
  writeFileSync(path, data);
};

const findFfmpeg = () => {
  const dir = join(root, "node_modules", "@remotion");
  const comp = readdirSync(dir).find((d) => d.startsWith("compositor-"));
  if (!comp) throw new Error("@remotion/compositor-* not installed (run npm ci)");
  return join(dir, comp, process.platform === "win32" ? "ffmpeg.exe" : "ffmpeg");
};

const ffmpeg = findFfmpeg();
rmSync(tmp, { recursive: true, force: true });
mkdirSync(tmp, { recursive: true });
mkdirSync(outDir, { recursive: true });
const durations = {};
for (const [name, design] of Object.entries(SOUNDS)) {
  const samples = normalize(design());
  const wav = join(tmp, `${name}.wav`);
  writeWav(wav, samples);
  execFileSync(ffmpeg, ["-y", "-loglevel", "error", "-i", wav, "-codec:a", "libmp3lame", "-b:a", "96k", join(outDir, `${name}.mp3`)]);
  durations[name] = Math.round((samples.length / SR) * 100) / 100;
}
rmSync(tmp, { recursive: true, force: true });
console.log(JSON.stringify(durations, null, 1));
